 if(d.claim!=null&&window.__res){const x=window.__res.res[+d.claim];S.claims.push({r:window.__res.r,ai:x.s,fact:x.hit.fact,ev:'근거: '+x.hit.ev});location.hash='#/done';return}
 if(b.id==='shareBtn'){const c=S.claims[S.claims.length-1];const txt=`[모두의 정답노트] AI는 “${c.ai}”라고 말했지만, 확인된 정답은 “${c.fact}”예요.`;(navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(()=>toast('공유 문구를 복사했어요.')).catch(()=>toast(txt));return}
 if(b.id==='propBtn'){const q=$('#pq').value.trim();const out=$('#propOut');if(!q){out.innerHTML='<p class="mute">질문을 적어 주세요.</p>';return}if(/(가장|추천|맛있|좋은|최고|어디가 나아)/.test(q)){out.innerHTML='<div class="notice"><b>이 질문은 측정하기 어려워요.</b><br>의견이나 추천을 묻는 질문은 정답을 정할 수 없어요. “○○ 운영 시간은?”처럼 확인할 수 있는 사실로 바꿔 볼까요?</div>';return}S.props.unshift({id:'p'+Date.now(),r:$('#pr').value,q,area:$('#pa').value,votes:1,status:'검토 중'});S.voted[S.props[0].id]=true;toast('제안을 받았어요. 정답(정본)을 확인한 뒤 다음 회차 후보가 돼요.');route();return}
 if(d.vote){if(S.voted[d.vote]){toast('이미 투표했어요 (지역별 1인 1표).');return}const p=S.props.find(x=>x.id===d.vote);p.votes++;S.voted[d.vote]=true;route();return}
