 if(d.obj){const v=($('#ob-'+d.obj)||{}).value||'';if(!v.trim()){toast('근거와 함께 의견을 적어 주세요.');return}S.objections.push({id:d.obj,t:v});toast('의견을 받았어요. 같은 기준으로 다시 판정해요.');route();return}
