 if(d.gl!=null){S.gloss[+d.gl][7]=2;toast('검수 완료. 다국어 답안지와 사실 페이지에 반영돼요.');route();return}
 if(b.id==='vSend'){const v=($('#vRep')||{}).value||'';const T=VT[d.l]||VT.en;if(!v.trim())return;S.claims.push({r:'jeju',ai:v,fact:'(다국어 검수 대기)',ev:'방문객 신고 · '+d.l});$('#vOut').textContent=T.thx;save();return}
 if(b.id==='printBtn'){toast('증빙 미리보기: 가명·활동 시간·품질이 담긴 월간 표를 출력해요 (데모).');return}
 if(b.id==='runBtn'){if(timer)return;timer=setInterval(()=>{S.run=Math.min(11520,S.run+960);if(S.run>=11520){clearInterval(timer);timer=null}if((location.hash||'').indexOf('#/ops/run')===0)route();else save()},400);return}
 if(b.id==='runReset'){if(timer){clearInterval(timer);timer=null}S.run=0;route();return}
